{
    #ifdef USE_WXPHP_DEBUG
    php_printf(
        "Calling php_wxAnimationDecoder_new on %s at line %i\n",
        zend_get_executed_filename(),
        zend_get_executed_lineno()
    );
    php_printf("===========================================\n");
    #endif

    zo_wxAnimationDecoder* custom_object;

    custom_object = (zo_wxAnimationDecoder*) ecalloc(
        1,
        sizeof(zo_wxAnimationDecoder)
        + zend_object_properties_size(class_type)
    );

    zend_object_std_init(&custom_object->zo, class_type);
    object_properties_init(&custom_object->zo, class_type);

    custom_object->zo.handlers = &wxphp_wxAnimationDecoder_object_handlers;

    custom_object->native_object = NULL;
    custom_object->object_type = PHP_WXANIMATIONDECODER_TYPE;
    custom_object->is_user_initialized = 0;

    return &custom_object->zo;
}
