void php_wxSharedClientDataContainer_free(void *object)
{
    zo_wxSharedClientDataContainer* custom_object = (zo_wxSharedClientDataContainer*) object;

    #ifdef USE_WXPHP_DEBUG
    php_printf(
        "Calling php_wxSharedClientDataContainer_free on %s at line %i\n",
        zend_get_executed_filename(),
        zend_get_executed_lineno()
    );
    php_printf("===========================================\n");
    #endif

    if(custom_object->native_object != NULL)
    {
        #ifdef USE_WXPHP_DEBUG
        php_printf("Pointer not null\n");
        php_printf("Pointer address %x\n", (unsigned int)(size_t)custom_object->native_object);
        #endif

        if(custom_object->is_user_initialized)
        {
            #ifdef USE_WXPHP_DEBUG
            php_printf("Deleting pointer with delete\n");
            #endif

            delete custom_object->native_object;
            custom_object->native_object = NULL;
        }

        #ifdef USE_WXPHP_DEBUG
        php_printf("Deletion of wxSharedClientDataContainer done\n");
        php_printf("===========================================\n\n");
        #endif
    }
    else
    {
        #ifdef USE_WXPHP_DEBUG
        php_printf("Not user space initialized\n");
        #endif
    }

    zend_object_std_dtor(&custom_object->zo);
    efree(custom_object);
}

zend_object* php_wxSharedClientDataContainer_new(zend_class_entry *class_type)
{
    #ifdef USE_WXPHP_DEBUG
    php_printf(
        "Calling php_wxSharedClientDataContainer_new on %s at line %i\n",
        zend_get_executed_filename(),
        zend_get_executed_lineno()
    );
    php_printf("===========================================\n");
    #endif

    zo_wxSharedClientDataContainer* custom_object;

    custom_object = (zo_wxSharedClientDataContainer*) ecalloc(
        1,
        sizeof(zo_wxSharedClientDataContainer)
        + zend_object_properties_size(class_type)
    );

    zend_object_std_init(&custom_object->zo, class_type);
    object_properties_init(&custom_object->zo, class_type);

    custom_object->zo.handlers = &wxphp_wxSharedClientDataContainer_object_handlers;

    custom_object->native_object = NULL;
    custom_object->object_type = PHP_WXSHAREDCLIENTDATACONTAINER_TYPE;
    custom_object->is_user_initialized = 0;

    return &custom_object->zo;
}
